15	
16	import java.util.Collection;
17	import java.util.List;
18	
19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public abstract class OwnerMapper {
24	
25	    @Autowired
26	    protected BulkSignupWarningEvaluator bulkSignupWarningEvaluator;
27	
28	    public abstract OwnerDto toOwnerDto(Owner owner);
29	
30	    public abstract Owner toOwner(OwnerDto ownerDto);
31	
32	    @Mapping(target = "id", ignore = true)
33	    @Mapping(target = "pets", ignore = true)
34	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
35	
36	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
37	
38	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
39	
40	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
41	        OwnerPageDto ownerPageDto = new OwnerPageDto();
42	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
43	        ownerPageDto.setPage(ownerPage.getNumber());
44	        ownerPageDto.setSize(ownerPage.getSize());
45	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
46	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
47	        return ownerPageDto;
48	    }
49	
